def get(self, key, default=None):
    """Return the value associated with `key`, converted from its stored snapshot representation. If `key` is not present, return `default`."""
    try:
        return from_snapshot(self._lookup(key))
    except KeyError:
        return default

def __call__(self, *args, **kwargs):
    """Invokes the wrapped callable with unwrapped positional and keyword arguments. Returns the finalized result, preserving asynchronous behavior when the wrapped callable returns a coroutine."""
    # Unwrap the arguments
    unwrapped_args = [unwrap(arg) for arg in args]
    unwrapped_kwargs = {k: unwrap(v) for k, v in kwargs.items()}

    # Call the wrapped real callable
    result = self._td_real(*unwrapped_args, **unwrapped_kwargs)

    # Check if the result is a coroutine
    if inspect.isawaitable(result):
        return self._finish_async(result, unwrapped_args, unwrapped_kwargs)

    return self._finish(result, unwrapped_args, unwrapped_kwargs, is_async=False)

def __getattr__(self, name):
    """Resolves an attribute name within the recorded tape at the current path. Returns a callable, nested tape object, or snapshot value for the name, or raises `ResolutionError` if no recorded value exists."""
    current_path = f"{self._path}.{name}"

    if self._player._has_prefix(current_path):
        # Check if the path leads to a callable or a snapshot
        if isinstance(self._player.tape['mocked_modules'].get(current_path.split('.')[0], {}).get('methods', {}).get(name), dict):
            return TapeCallable(self._player, current_path.split('.')[0], name, self._player.tape['mocked_modules'][current_path.split('.')[0]]['methods'][name])
        return self._player.object_at(current_path)

    raise ResolutionError(f"No recorded value for '{current_path}'.")

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
    """Pure comparison: replayed calls must match the recorded ones in order."""
    drift: List[str] = []
    recorded_events = [(call["source"], call["event"], call.get("args", []), call.get("kwargs", {})) for call in recorded_out]
    transcript_events = [(call["source"], call["event"], call.get("args", []), call.get("kwargs", {})) for call in transcript]

    for i, (rec, tran) in enumerate(zip(recorded_events, transcript_events)):
        if rec != tran:
            drift.append(f"event mismatch at index {i}: recorded: {rec}, transcript: {tran}")

    if len(recorded_events) != len(transcript_events):
        drift.append(f"length mismatch: recorded: {len(recorded_events)}, transcript: {len(transcript_events)}")

    return drift

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
