    if len(recorded_out) != len(transcript):
        drift.append(f"length mismatch: recorded: {len(recorded_out)}, transcript: {len(transcript)}")

    # Use zip to compare the items from both lists in order
    for i, (rec, tran) in enumerate(zip(recorded_out, transcript)):
        if rec.get("event") != tran.get("event"):
            drift.append(f"event mismatch at index {i}: recorded: {rec.get('event')}, transcript: {tran.get('event')}")
        if rec.get("args") != tran.get("args"):
            drift.append(f"args mismatch at index {i}: recorded: {rec.get('args')}, transcript: {tran.get('args')}")
        if rec.get("kwargs") != tran.get("kwargs"):
            drift.append(f"kwargs mismatch at index {i}: recorded: {rec.get('kwargs')}, transcript: {tran.get('kwargs')}")

    return drift

def __getattr__(self, name):
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if callable(value):
        return CallableWrapper(value, self._rec, self._red, self._module_path, name)
    if _should_wrap_result(value):
        return ObjectProxy(value, self._rec, self._red, f"{self._module_path}.{name}")
    return value

def __getattr__(self, name):
    """Delegates attribute access to the wrapped object, returning private attributes unchanged.
    Wraps public classes, modules, and callables in proxy objects while returning other values directly."""
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if callable(value) and not inspect.isclass(value):
        return CallableWrapper(value, self._rec, self._red, self._td_real.__name__, name)
    if _should_wrap_result(value):
        return ObjectProxy(value, self._rec, self._red, f"{self._td_real.__name__}.{name}")
    return value

def diff_tapes(old: dict, new: dict) -> List[str]:
    """Pure drift report: how the newly captured behaviour differs from the old
    tape. Empty list = the recording is still true."""

    drift_report = []

    # Check for removed methods
    for module, methods in old.get("mocked_modules", {}).items():
        if module not in new.get("mocked_modules", {}):
            drift_report.append(f"module removed: {module}")
            continue

        for method, method_info in methods.get("methods", {}).items():
            if method not in new["mocked_modules"][module]["methods"]:
                drift_report.append(f"method removed: {module}.{method}")

    # Check for return shape changes
    for module, methods in old.get("mocked_modules", {}).items():
        if module in new.get("mocked_modules", {}):
            for method, method_info in methods.get("methods", {}).items():
                if method in new["mocked_modules"][module]["methods"]:
                    old_return = method_info.get("return_value")
                    new_return = new["mocked_modules"][module]["methods"][method].get("return_value")

                    if old_return != new_return:
                        drift_report.append(f"return shape changed: {module}.{method}")

    # Check for schema field changes
    for schema_name, old_schema in old.get("nested_schemas", {}).items():
        new_schema = new.get("nested_schemas", {}).get(schema_name, {})
        for field in old_schema:
            if field not in new_schema:
                drift_report.append(f"fields removed from schema {schema_name}: {field}")
        for field in new_schema:
            if field not in old_schema:
                drift_report.append(f"fields added to schema {schema_name}: {field}")

    # Check for inbound events
    old_events = {event["event"]: event for event in old.get("timeline", []) if event["dir"] == "in"}
    new_events = {event["event"]: event for event in new.get("timeline", []) if event["dir"] == "in"}

    for event_name in old_events:
        if event_name not in new_events:
            drift_report.append(f"no longer seen: {old_events[event_name]['source']}:{event_name}")

    for event_name in new_events:
        if event_name not in old_events:
            drift_report.append(f"new inbound event: {new_events[event_name]['source']}:{event_name}")

    return drift_report

