def render_json(report) -> dict:
    """Lines with their status, findings, and the evidence per test: which tests ran each
    changed line, which noticed its mutant, and what each of those tests fakes. Tools that
    know what a test is *for* (specdeck's requirements) join on the node ids."""

    from collections import defaultdict

    result = {
        "lines": [],
        "tests": [],
        "findings": [],
        "reach": []
    }

    # Collect data about lines
    for (path, line), status in report.lines.items():
        line_info = {
            "line": line,
            "status": status.name.lower()
        }
        if status == LineStatus.IMPORT_TIME:
            line_info["at_import"] = True
        else:
            line_info["at_import"] = False

        # Find tests related to the line
        ran_by = [test.nodeid for test in report.tests if line in test.ran_lines]
        line_info["ran_by"] = ran_by

        # Finding the test that killed the mutant (if applicable)
        killed_by = [test.nodeid for test in report.findings if test.line == line and test.kind == FindingKind.SURVIVING_MUTANT]
        line_info["killed_by"] = killed_by

        result["lines"].append(line_info)

    # Collect data about tests
    test_data = {}
    for test in report.tests:
        test_entry = {
            "nodeid": test.nodeid,
            "fakes": list(test.fakes)  # Store fakes used by the test
        }
        test_data[test.nodeid] = test_entry

    result["tests"] = list(test_data.values())

    # Collect findings
    for finding in report.findings:
        finding_info = {
            "kind": finding.kind.name,
            "line": finding.line,
            "message": finding.message,
            "path": finding.path
        }
        result["findings"].append(finding_info)

    # Collect reach data
    for (path, line), info in report.reach.items():
        reach_info = {
            "function": info["function"],
            "depth": info["depth"]
        }
        result["reach"].append(reach_info)

    return result

