def is_arid(source: str, line: int) -> bool:
    """True when `line` of `source` should never be mutated."""
    import ast

    tree = ast.parse(source)
    lines = source.splitlines()

    if line < 1 or line > len(lines):
        return False

    node_to_check = None
    for node in ast.walk(tree):
        if hasattr(node, 'lineno') and node.lineno == line:
            node_to_check = node
            break

    if node_to_check is None:
        return False

    if isinstance(node_to_check, (ast.Import, ast.ImportFrom)):
        return True

    if isinstance(node_to_check, ast.Expr) and is_docstring(node_to_check):
        return True

    if isinstance(node_to_check, ast.FunctionDef):
        if any(isinstance(arg, ast.arg) and arg.default for arg in node_to_check.args.args):
            return True

    if isinstance(node_to_check, ast.Call) and _is_noise_call(node_to_check):
        return True

    if _in_main_guard(node_to_check, {n: p for p, n in zip(ast.walk(tree), [parent for parent in ast.walk(tree)])}):
        return True

    return False

def vacuous_assertions(test_source: str, path: str = "<test>") -> list:
    """Returns findings for assertions in the given test source that appear vacuous, such as always-true checks or assertions that only verify type or non-None status. The optional path is included in each finding, and invalid source returns an empty list."""
    test_tree = _parse(test_source)
    if test_tree is None:
        return []

    found = []
    for node in ast.walk(test_tree):
        if isinstance(node, ast.Assert):
            if isinstance(node.test, ast.Name) and node.test.id == 'True':
                found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
            elif isinstance(node.test, ast.Compare) and len(node.test.ops) == 1:
                if (isinstance(node.test.left, ast.Name) and node.test.ops[0].__class__.__name__ == 'Eq'
                        and isinstance(node.test.comparators[0], ast.Constant)
                        and node.test.comparators[0].value is None):
                    found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
                elif (isinstance(node.test.left, ast.Name) and isinstance(node.test.comparators[0], ast.Name) 
                        and node.test.comparators[0].id == node.test.left.id):
                    found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
                elif (isinstance(node.test.left, ast.Call) and isinstance(node.test.comparators[0], ast.Name) 
                        and node.test.comparators[0].id == 'None'):
                    found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
                elif (isinstance(node.test.left, ast.Name) and 
                      any(isinstance(node.test.comparators[0], ast.Num) for _ in _literal(node.test.comparators[0]))):
                    found.append(Finding(FindingKind.VACUOUS_ASSERTION, path, node.lineno, MSG_VACUOUS))
    return found

