def exit_code(report, gate: bool = True) -> int:
    """1 when gating and something is unverified: a surviving mutant, a changed line no test runs,
    a weakened test or a checker change. Unconfirmed expectations and the other detectors are
    advisory and never fail the gate on their own."""
    if not gate:
        return 0

    # Check for findings that will fail the gate
    for finding in report.findings:
        if finding.kind in GATING:
            return 1
    return 0

def exit_code(report, gate: bool = True) -> int:
    """1 when gating and something is unverified: a surviving mutant, a changed line no test runs,
    a weakened test or a checker change. Unconfirmed expectations and the other detectors are
    advisory and never fail the gate on their own."""
    if not gate:
        return 0

    # Check if there are any findings that will fail the gate
    for finding in report.findings:
        if finding.kind in GATING or finding.kind in {FindingKind.REQUIREMENT_CHANGED, FindingKind.UNCONFIRMED_EXPECTATION}:
            return 1

    # Check for lines not run by any tests
    never_ran_lines = _never_ran(report)
    if never_ran_lines:
        return 1

    return 0

def faked(repo, nodeid: str) -> list:
    """Names this test replaces with fakes; [] if it uses none."""
    import ast

    path = repo / nodeid.split("::")[0]
    tree = ast.parse(path.read_text(encoding="utf-8"))
    fakes = []

    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and _target(node):
            fakes.append(_target(node))

    return fakes

