def select(candidates: dict, cap_per_file: int = 7) -> list:
    """At most one mutant per line (its first, most useful candidate), at most `cap_per_file` per file.

    `candidates`: {path: {line: [Mutant, ...]}}. Lines are taken top to bottom.
    """
    selected = []
    counts = {path: 0 for path in candidates.keys()}

    for path, lines in candidates.items():
        for line, mutants in sorted(lines.items()):
            if counts[path] >= cap_per_file:
                break
            if mutants:
                selected.append(mutants[0])  # Take the first (most useful) candidate
                counts[path] += 1

    return selected

def exit_code(model: dict, *, fail_on_failing=False, fail_on_unmet=False, fail_on_untrusted=False) -> int:
    """Return an exit status for a results model, optionally treating failing checks, unmet requirements, or untrusted items as errors. Returns 1 when an enabled failure condition is present, otherwise 0."""
    exit_status = 0

    # Check for failing scenarios
    if fail_on_failing and model['counts']['failing'] > 0:
        exit_status = 1

    # Check for unmet requirements
    if fail_on_unmet and model.get('requirements', {}).get('counts', {}).get('failing', 0) > 0:
        exit_status = 1

    # Check for untrusted items
    if fail_on_untrusted and model.get('trust') and model['trust'].get('requirements', []):
        untrusted_count = sum(1 for r in model['trust']['requirements'] if r['status'] != 'met')
        if untrusted_count > 0:
            exit_status = 1

    return exit_status

