def stop(self) -> dict:
    """``{nodeid: {(abs path, line)}}``, import-time lines removed."""
    if self._cov is None:
        return {}
    self._cov.stop()
    data = self._cov.get_data()

    # gather line numbers for each context
    result = {}
    for context in data.measured_files():
        covered_lines = data.lines(context)
        abs_path = data.path(context)
        for line in covered_lines:
            result.setdefault(self._cov.current_context(), set()).add((abs_path, line))

    # switch back to our default context to remove the import context data
    self._cov.switch_context(IMPORT_CONTEXT)
    if IMPORT_CONTEXT in result:
        del result[IMPORT_CONTEXT]

    return {nodeid: list(lines) for nodeid, lines in result.items()}

