def validate_requirements_file(path) -> list:
    """Diagnostics for a hand-written requirements file.

    ``requirements.load`` already collects its own problems rather than raising;
    this turns them into the same Diagnostic shape so one command reports both.
    """
    from pathlib import Path
    import yaml

    p = Path(path)
    if not p.exists():
        return [Diagnostic("error", "NO_FILE", f"Requirements file {p} does not exist.")]

    try:
        text = p.read_text(encoding="utf-8")
        data = yaml.safe_load(text)
    except OSError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"Cannot read {p}: {e}")]
    except yaml.YAMLError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"{p} is not valid YAML: {e}")]

    if data is None or not isinstance(data, dict) or 'requirements' not in data:
        return [Diagnostic("error", "NO_REQUIREMENTS", f"Requirements file {p} must contain a 'requirements' key.")]

    diags = []
    seen_ids = set()

    for i, req in enumerate(data['requirements']):
        path = f"requirements[{i}]"
        if not isinstance(req, dict):
            diags.append(Diagnostic("error", "BAD_REQUIREMENT", f"Requirement must be a mapping, found {type(req).__name__}.", path=path))
            continue

        req_id = str(req.get("id") or "")
        if not req_id:
            diags.append(Diagnostic("error", "REQUIREMENT_NO_ID", "Requirement has no `id`.", path=path))
        elif req_id in seen_ids:
            diags.append(Diagnostic("error", "DUP_REQUIREMENT", f"Duplicate requirement id `{req_id}`.", path=path))
        else:
            seen_ids.add(req_id)

        for key in req:
            if key != "id" and key != "says":
                diags.append(Diagnostic("warning", "UNKNOWN_KEY", f"Unknown requirement key `{key}`.", path=path))

    return diags

def validate_requirements_file(path) -> list:
    """Diagnostics for a hand-written requirements file.

    ``requirements.load`` already collects its own problems rather than raising;
    this turns them into the same Diagnostic shape so one command reports both.
    """
    from pathlib import Path
    import yaml

    p = Path(path)
    if not p.exists():
        return [Diagnostic("error", "NO_FILE", f"Requirements file {p} does not exist.")]

    try:
        text = p.read_text(encoding="utf-8")
        data = yaml.safe_load(text)
    except OSError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"Cannot read {p}: {e}")]
    except yaml.YAMLError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE", f"{p} is not valid YAML: {e}")]

    if data is None or not isinstance(data, dict) or 'requirements' not in data:
        return [Diagnostic("error", "NO_REQUIREMENTS", f"Requirements file {p} must contain a 'requirements' key.")]

    diags = []
    seen_ids = set()

    for i, req in enumerate(data['requirements']):
        path = f"requirements[{i}]"
        if not isinstance(req, dict):
            diags.append(Diagnostic("error", "BAD_REQUIREMENT", f"Requirement must be a mapping, found {type(req).__name__}.", path=path))
            continue

        req_id = str(req.get("id") or "")
        if not req_id:
            diags.append(Diagnostic("error", "REQUIREMENT_NO_ID", "Requirement has no `id`.", path=path))
        elif req_id in seen_ids:
            diags.append(Diagnostic("error", "DUP_REQUIREMENT", f"Duplicate requirement id `{req_id}`.", path=path))
        else:
            seen_ids.add(req_id)

        for key in req:
            if key not in ["id", "says"]:
                diags.append(Diagnostic("warning", "UNKNOWN_KEY", f"Unknown requirement key `{key}`.", path=path))

    # If there are duplicates, we need to report it as a requirement diagnostic
    if any(d.code == "DUP_REQUIREMENT" for d in diags):
        diags.append(Diagnostic("warning", "REQUIREMENT", "There are duplicates in requirements."))

    return diags

def snapshot(root: Path) -> dict:
    """path -> signature for every watched file under root."""
    from pathlib import Path

    signatures = {}
    for path in root.rglob("*"):
        if path.is_file() and path.suffix in WATCH_SUFFIXES:
            if not any(path.match(f"{dir}/*") for dir in IGNORE_DIRS):
                signatures[str(path)] = _signature(path)
    return signatures
